<label for="date_from" style="display: inline; margin-bottom: 10px; font-weight: bold; color: #333;">Select Start Date:</label>
<input type="date" id="date_from" name="date_from" style="width: calc(25% - 5px); margin-bottom: 20px; padding: 10px; border: 1px solid #ccc; border-radius: 4px; box-sizing: border-box;">
<label for="date_to" style="display: inline; margin-bottom: 10px; font-weight: bold; color: #333;">Select End Date:</label>
<input type="date" id="date_to" name="date_to" style="width: calc(25% - 5px); margin-bottom: 20px; padding: 10px; border: 1px solid #ccc; border-radius: 4px; box-sizing: border-box;">
<button id="generateChartBtn" style="padding: 10px 20px; background-color: #4267B2; color: #fff; border: none; border-radius: 4px; cursor: pointer; font-size: 16px; transition: background-color 0.3s;">Generate Chart</button>
